from collections import defaultdict
from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr = self.find(x)
        yr = self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        uf = UnionFind(n)

        # Step 1: Prime factorization
        prime_factors = defaultdict(set)
        for i, num in enumerate(nums):
            for factor in self.prime_factors(num):
                prime_factors[factor].add(i)

        # Step 2: Union-Find
        for factor in prime_factors:
            for i in prime_factors[factor]:
                for j in prime_factors[factor]:
                    if i != j:
                        uf.union(i, j)

        # Step 3: Check connectedness
        root = uf.find(0)
        for i in range(1, n):
            if uf.find(i) != root:
                return False
        return True

    def prime_factors(self, n):
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                yield i
        if n > 1:
            yield n
